// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address user) public {
        vm.assume(user != address(0) && user != address(this));
        vm.prank(address(this));
        c.rely(user);
        vm.prank(user);
        c.rely(user);
        assertTrue(c.wards(user) == 1);
    }
}
